var e={about:{title:"Om kortet",hiking:"<p>Dette kort viser skiltede vandreruter rundt om i verden.</p>\n",cycling:"<p>Dette kort viser skiltede cykelruter rundt om i verden.</p>\n",mtb:"<p>Dette kort viser skiltede mountainbikeruter rundt om i verden.</p>\n",skating:"<p>Dette kort viser skiltede inline-skatingruter rundt om i verden.</p>\n",riding:"<p>Dette kort viser skiltede rideruter rundt om i verden.</p>\n",slopemap:"<p>Dette kort viser skiltede vintersportspister rundt om i verden.</p>\n",osm:'<p>Ruterne vises oven på det almindelige OpenStreetMap-kort og eventuelt et højdeprofillag. Rutekortet er dannet ud fra <a href="https://www.openstreetmap.org">OpenStreetMap-projektets</a> (OSM) data.\nOSM er et frit redigerbart verdenskort, som alle kan bidrage til. Det betyder, at det langt fra er komplet,\nmen det betyder også, at du kan bidrage ved at tilføje nye ruter og rette fejl i dem, der allerede er der.\nSe <a href="https://wiki.openstreetmap.org/wiki/Da:Beginners%27_guide">Guide til nybegyndere</a> for flere oplysninger om OpenStreetMap.</p>\n'},rendering:{title:"Visning af OSM-data",hikingroutes:'<p>Vandreruter skal lægges ind i OSM som relationer. Præcis hvordan det fungerer,\ner forklaret i detaljer på tagging-siden om\n<a href="https://wiki.openstreetmap.org/wiki/Walking_Routes">vandreruter</a>\ni OSM-wikien. Dette kort viser relationer, der har mindst et af følgende tags:</p>\n<p>type = route|superroute\nroute = foot|walking|hiking</p>\n',cyclingroutes:'<p>Cykelruter skal lægges ind i OSM som relationer. Præcis hvordan det fungerer,\ner forklaret i detaljer på siden om\n<a href="https://wiki.openstreetmap.org/wiki/Cycle_routes">cykelruter</a>\ni OSM-wikien. Dette kort viser relationer, der har mindst et af følgende tags:</p>\n<p>type = route|superroute\nroute = bicycle</p>\n<p>Mountainbikeruter vises på et særskilt <a href="https://mtb.waymarkedtrails.org">MTB-kort</a>.</p>\n',mtbroutes:'<p>Mountainbikeruter tagges efter samme princip som cykelruter,\nder er forklaret i detaljer på siden om\n<a href="https://wiki.openstreetmap.org/wiki/Cycle_routes">cykelruter</a>\ni OSM-wikien. Relationer med de følgende tags vises som mountainbikeruter:</p>\n<p>type = route|superroute\nroute = mtb</p>\n<p>Almindelige cykelruter vises på et særskilt <a href="https://cycling.waymarkedtrails.org">cykelkort</a>.</p>\n',skatingroutes:'<p>Skiltede skatingruter bør tagges efter samme princip som enhver anden type ruterelation.\nFor de tagging-regler, dette kort kan forstå, se wikisiden om\n<a href="https://wiki.openstreetmap.org/wiki/Switzerland/InlineNetwork">inline-skatingruter i Schweiz</a>.\nFor at en rute skal kunne genkendes som en skatingrute, skal de følgende tags være til stede:</p>\n<p>type = route|superroute\nroute = inline_skates</p>\n',ridingroutes:'<p>Skiltede hestestier skal tagges på samme måde som enhver anden ruterelation.\nFor detaljer se <a href="https://wiki.openstreetmap.org/wiki/Relation:route">rutesiden i OSM-wikien</a>.\nFor at blive genkendt som en hestesti, skal de følgende tags være til stede:</p>\n<pre><code>type = route|superroute\nroute = horse\n</code></pre>\n',sloperoutes:"<p>Skiltede pister er ruter med taggene piste:type.\nFor at blive genkendt som en piste, skal de følgende tags være til stede:</p>\n<pre><code>piste:type = downhill|nordic|sled|hike|sleigh\n</code></pre>\n<p>For relationer skal de følgende tags være til stede:</p>\n<pre><code>type = route|superroute\nroute = ski|piste\npiste:type = downhill|nordic|sled|hike|sleigh\n</code></pre>\n",slopeclassification:"<p>Klassifikationen af skipister (nedad) bestemmes af tagget <code>piste:difficulty</code> og bruges for farven i gengivelsen.</p>\n",classification:"<p>Klassificeringen (og dermed også rutens farve på kortet) bestemmes ud fra <code>network</code>-tagget.</p>\n",slopemaplabels:"<p>Etiketten for skipister (nedad) &quot;gættes&quot; ud fra taggende i den følgende rækkefølge:</p>\n<ol>\n<li>Hvis et <code>piste:ref</code>-tag findes, lav en tekstetiket med tagget <code>piste:ref</code>.</li>\n<li>Hvis et <code>piste:name</code> findes, afled en reference fra denne,\nved først udelukkende at bruge store bogstaver og hvis det\nfejler ved at bruge de første bogstaver i navnet.</li>\n<li>Hvis et <code>ref</code>-tag findes, lav en tekstetiket med tagget <code>ref</code>.</li>\n<li>Hvis det er en relation og et <code>name</code>-tag findes, afled en\nreference fra denne, først ved udelukkende at bruge store\nbogstaver og hvis dette fejler ved at bruge de første bogstaver\ni navnet.</li>\n<li>Giv op.</li>\n</ol>\n<p>Nordiske pister er markeret med et tegn, der alene viser deres farve, hvis et farve-tag er til stede.</p>\n",hikinglabels:'<p>Etiketten på den enkelte rute bestemmes ud fra dens tags efter følgende regler:</p>\n<ol>\n<li>Kontroller om der er <a href="#help-hikinglocal">regler for at tilpasse visningen til lokale forhold</a>.</li>\n<li>Forsøg at tolke <code>osmc:symbol</code>-tagget. For detaljer om hvordan tagget tolkes,\nse <a href="osmc_symbols.html">regler for visning af oscm:symbolet</a>.</li>\n<li>Hvis der er et <code>ref</code>-tag, brug det til etiketteteksten.</li>\n<li>Hvis der er et <code>name</code>-tag, så udled en reference fra det, ved først kun at brug de af bogstaverne, der er skrevet med stort, eller hvis\ndet ikke virker, brug de første bogstaver i navnet.</li>\n<li>Giv op.</li>\n</ol>\n',labels:"<p>Etiketten på den enkelte rute bestemmes ud fra dens tags efter følgende regler:</p>\n<ol>\n<li>Hvis der er et <code>ref</code>-tag, brug det til teksten.</li>\n<li>Hvis der er et <code>name</code>-tag, så brug de af bogstaverne, der er skrevet med stort, eller hvis\ndet ikke virker, brug de første bogstaver i navnet.</li>\n<li>Giv op.</li>\n</ol>\n",hierarchy:'<p>Kortet understøtter også <a href="#help-hierarchies">relationshierarkier</a>.</p>\n',guideposts:'<p><a href="https://wiki.openstreetmap.org/wiki/Da:Tag:information%3Dguidepost">Vejvisere</a> med disse tags bliver vist:</p>\n<p>tourism=information\ninformation=guidepost\nname=&lt;navn&gt;\nele=&lt;højde&gt;</p>\n<p><code>tourism</code> og <code>information</code> er obligatoriske. <code>name</code> og <code>ele</code> kan udelades.</p>\n'},route_order:{title:"Rækkefølge af ruter",text:"<p>waymarkedtrails skal have ordentligt sorteret rute for at vise højdeprofilen og for at downloade GPX og KML. Når den analyserer en rute, forsøger den så vidt muligt at respektere rækkefølgen af medlemslinjestrengene i relationen, fordi det gør det nemmere for kortlæggere at påvirke rækkefølgen uden at skulle prøve sig frem. Hvis en relation synes at være uordnet, vil waymarkedtrails stadig sætte linjestrengene i en rækkefølge, hvis og kun hvis linjestrengene kan danne en ubrudt lineær rute.</p>\n<p>Relationsrollerne tages i betragtning ved sortering af ruten. <code>forward</code> og <code>backward</code> roller kan anvendes til at markere sektioner, hvor ruten skal følges på forskellige dele afhængigt af retning. Husk at disse roller er defineret i forhold til linjestrengens retning, ikke ruten! Hvis der er tale om en sådan delt sektion, skal du sørge for, at linjestrengene for hver retning vises direkte efter hinanden i forholdet, og at linjestrengene stadig følger rutenes rækkefølge.</p>\n<p>Alle andre roller betragtes som sidespor i den ene eller den anden form og ignoreres for den generelle sortering af ruten. De vises stadig på kortet.</p>\n<p>waymarkedtrails er i stand til at håndtere uadskillede rundkørsler inden for en rute. Tilføj blot den lukkede linjestreng uden nogen rolle, og rundkørslen vil blive opdelt i passende sektioner. Dette fungerer også, når der er en V-tilkørsel til rundkørslen, som er opdelt i fremad og bagud. Der er to tilfælde, hvor denne håndtering fejler:</p>\n<ul>\n<li>hvis rundkørslen af en eller anden grund blev opdelt på flere linjestrenge, skal man tilføje dele med de relevante <code>forward</code> og <code>backward</code> roller.</li>\n<li>hvis rundkørslen er en del af en retningssektion, skal du opdele rundkørslen og tilføje den anvendte del med den passende rolle.</li>\n</ul>\n<p>Generel tommelfingerregel for rækkefølge: Hvis JOSM-relationseditoren viser ruten som kontinuerlig, bør waymakedtrails også kunne vise en lineær rute.</p>\n"},hierarchies:{title:"Relationshierarki",text:'<p>Kortet understøtter også relationer, der indeholder andre relationer.  Disse hierarkier bruges på to forskellige måde i OSM-databasen: de bruges enten til at opdele meget lange ruter (f.eks. <a href="https://hiking.waymarkedtrails.org/#route?id=36367">E1</a>), eller de bruges til at undgå dobbeltarbejde, når to ruter følger den samme linjestreng (se for eksempel den schweiziske <a href="https://hiking.waymarkedtrails.org/#route?id=124582">Via Francigena</a>, der indgår som en del af den europæiske <a href="https://hiking.waymarkedtrails.org/#route?id=11860709">Via Romea Francigena</a>).\nI det første tilfælde udgør underrelationerne ikke komplette ruter, og de bør derfor ikke vises uafhængigt af resten af ruten på kortet.</p>\n<p>Hvordan præcist en underrelation håndteres under tegningen af kortet afhænger af <code>network</code>-tagget:</p>\n<ul>\n<li>Hvis en over- og underrelation har samme network-tag, betragtes underrelationen kun som et stykke af overrelationen. Det vil sige, at dens rute tilføjes til overrelationen, og underrelationen vises ikke på kortet.</li>\n<li>Hvis over- og underrelationerne har forskellige network-tags, betragtes relationen som uafhængig. Ruten for underrelationen tilføjes til overrelationen, og begge relationer vises på kortet.</li>\n</ul>\n<p><em>Bemærk:</em> Du kan altid se nærmere på underrelationer ved hjælp af rutebrowseren. Du kan ganske enkelt vælge overrelationen, og så vises en liste, hvor du kan vælge mellem underrelationerne.</p>\n'},osmc:{title:"osmc:symbol-tagget",text:'<p>Tagget <code>osmc:symbol</code> gør det muligt at beskrive rutemarkører på en maskinlæsbar måde. Det er primært beregnet til symboler, der, der består af simple geometriske former. For en fuld beskrivelse og\nhistorie om tagget, besøg wiki-siden <a href="https://wiki.openstreetmap.org/wiki/Key:osmc:symbol">osmc:symbol page</a> på OSM wiki. waymarkedtrails følger stort set det syntaks, der er beskrevet\npå wiki-siden med nogle begrænsninger og udvidelser, der er beskrevet her.</p>\n<p>For at blive gengivet på kortet, skal tagget have et af følgende formater:</p>\n<pre><code>waycolor:background\nwaycolor:background:foreground\nwaycolor:background:foreground:foreground2\nwaycolor:background:foreground:foreground2:text:textcolor\nwaycolor:background:foreground:text:textcolor\n</code></pre>\n<p><code>waycolor</code> skal altid være til stede, men ignoreres i dette kort. Derudover skal du angive en baggrund, selvom du kan lade feltet være tomt. Dernæst følger maksimalt to forskellige forgrunde. Til sidst kan man eventuelt tilføje en lille henvisningstekst, som tilføjes ovenpå. Tekstens farve skal altid angives. Bemærk, at waymarkedtrails ignorerer referencetekster, når de bliver for lange.\nHvor lang teksten kan være, afhænger af de valgte baggrunde: har en hård grænse på 4 tegn, diamantformede baggrunde tager kun et enkelt tegn, stribe- og bjælkeformede baggrunde tager ingen referencetekst overhovedet.</p>\n',reference_footer:"<p>Du kan finde den fulde liste over farver og former, som waymarkedtrails\nkan gengive, i referencen nedenfor.</p>\n",footer:'<p>Se den ekstra <a href="osmc_symbols.html">osmc:symbol</a> tag-side for en liste over symboler, der er\nunderstøttet af Waymarked Trails.</p>\n'},hikinglocal:{title:"Visning tilpasset lokale forhold",text:"<p>Der findes mange forskellige systemer til at markere vandreruter rundt om i verden. Selv om dette kort forsøger at bruge de mest generelle tags og vise dem godt, så vil det uundgåeligt gå galt med bestemte systemer og især med netværk af vandreruter. Det er muligt i udvalgte områder at tilpasse kortet til disse systemer, når standardvisningen er utilstrækkelig.</p>\n<p>Nedenfor er en liste over områder, der bruger specielle kortsymboler. Hvis du ønsker kortet tegnet på en speciel måde i dit område, så læs anvisningerne nederst på siden.</p>\n",swiss:'<h2>Schweiz</h2>\n<p>Schweiz har et omfattende netværk af afmærkede vandreruter, der dækker hele landet. Netværket er et knudenetværk, hvor navngivne vejviserskilte udgør knuderne. Alle stier er gennemgående tagget efter sværhedsgrad. Kortet viser disse stier i rødt med et stregmønster, der angiver sværhedsgraden:</p>\n<ul>\n<li><img src="img/route_std.png" alt="red line"> <em>vandrerute</em>, tagget med <img src="img/yellow_diamond.svg" alt="diamond">. Tagget med <code>network=lwn</code> og <code>osmc:symbol=yellow:[...]:yellow_diamond</code>.</li>\n<li><img src="img/route_mnt.png" alt="dashed line"> <em>bjergsti</em>, tagget med <img src="img/white_red_bar.svg" alt="white-red-white">. Tagget med <code>network=lwn</code> og <code>osmc:symbol=red:white:red_bar</code>.</li>\n<li><img src="img/route_alp.png" alt="dotted line"> <em>alpin sti</em>, tagget med <img src="img/white_blue_bar.svg" alt="white-blue-white">. Tagget med <code>network=lwn</code> og <code>osmc:symbol=blue:white:blue_bar</code>.</li>\n</ul>\n<p>Bemærk at udover dette netværk er der også nationale og regionale ruter, der vises som normalt.</p>\n<p>For flere oplysninger om tagging af vandreruter i Schweiz i OSM, se <a href="https://wiki.openstreetmap.org/wiki/Switzerland/HikingNetwork">det schweiziske vandrenetværk</a>.</p>\n',austria:'<h2>Østrig</h2>\n<p>Regionen Vorarlberg bruger et lignende klassifikationssystem som Schweiz. Ruter med tags <code>operator=Land Vorarlberg</code>, <code>network=rwn</code>\nog <code>network:type=basic_network</code> vil blive markeret efter et sværhedsbaseret system:</p>\n<ul>\n<li><img src="img/route_std.png" alt="red line"> osmc:symbol=yellow:white:yellow_upper</li>\n<li><img src="img/route_mnt.png" alt="dashed line"> osmc:symbol=red:white:red_bar</li>\n<li><img src="img/route_alp.png" alt="dotted line"> osmc:symbol=blue:white:blue_bar</li>\n</ul>\n',italy:'<h2>Italien</h2>\n<p>Italian Alpine club (CAI) vedligeholder netværket af bjergstier, som er klassificeret ved sværhedsgrad svarende til hvad der findes i Schweitz.\nRuter markeret med <code>network=lwn</code>, <code>osmc:symbol=red:..</code> og <code>cai_scale</code>-tag vil blive genkendt som CAI-vedligeholdte stier og vist som røde linjer jævnfør deres sværhedsgrad.</p>\n<ul>\n<li><img src="img/route_std.png" alt="rød linje"> cai_scale=T</li>\n<li><img src="img/route_mnt1.png" alt="stiplet linje"> cai_scale=E</li>\n<li><img src="img/route_mnt2.png" alt="stiplet linje"> cai_scale=EE</li>\n<li><img src="img/route_alp.png" alt="prikket linje"> cai_scale=EEA*</li>\n</ul>\n',uk:'<h2>Storbritannien</h2>\n<p>Klassifikationen af <a href="https://wiki.openstreetmap.org/wiki/WikiProject_United_Kingdom_Long_Distance_Paths">langdistancestier i Storbritannien</a> (dem, der tagges med <code>network=uk_ldp</code>) afhænger af <code>operator</code>-tagget. Relationer, der har <code>operator=National Trails</code>, vises som nationale ruter, og alle andre vises som regionale ruter.</p>\n<p>Relationer med et <code>network=lwn/rwn/nwn/iwn</code>-tag vises som sædvanligt.</p>\n',czech:'<h2>Tjekkiet</h2>\n<p>Tjekkiet bruger et system baseret på 7 forskellige symboler i 4 forskellige farver til at markere ruter. Se beskrivelsen på <a href="https://wiki.openstreetmap.org/wiki/WikiProject_Czech_Republic/Editing_Standards_and_Conventions#Doporu.C4.8Den.C3.A9_typy_cest">siden om tagging i Tjekkiet</a> (kun på tjekkisk).</p>\n<p>Når der er et <code>kct_*</code>-tag, foretrækkes det frem for et <code>osmc:symbol</code>-tag. Derudover vil ruten blive omklassificeret, hvis der ikke er gyldigt netværkstag. Ruter med <code>kct_red=major</code> bliver nationale ruter, og andre <code>kct_*=major</code>-ruter bliver klassificeret som regionale.</p>\n',slovakia:'<h2>Slovakiet</h2>\n<p>Slovakiet bruger det samme system til at markere vandreruter som Tjekkiet. Dog tagges de på en lidt anden måde, se <a href="https://wiki.openstreetmap.org/wiki/WikiProject_Slovakia/Hiking_routes">siden om vandreruter i Slovakiet</a>.</p>\n<p>Alle ruter med et <code>operator=KST</code>-tag håndteres i henhold til det system. Da ruter i Slovakiet bør have et gyldigt netværkstag, bliver de ikke omklassificeret.</p>\n',hungary:'<h2>Ungarn</h2>\n<p>Ungarn bruger også et system med et fast sæt af symboler i forskellige farver. Disse markeres med et specielt tag, <a href="https://wiki.openstreetmap.org/wiki/Key:jel">jel</a>.\nDette tag bliver givet større prioritet end et eventuelt <code>osmc:symbol</code>-tag.</p>\n',germany:"<h2>Tyskland</h2>\n<h3>Fränkischer Albverein</h3>\n<p>Netværket ved Nürnberg er ganske tæt, derfor vil regionale ruter med tagget <code>operator=Fränkischer Albverein</code> blive vist på lavere zoomniveauer end normalt.</p>\n",ukcycle:"<h2>Storbritannien</h2>\n<h3>Norwich</h3>\n<p>Norwich har et system af farvekodede ruter. Ruter med tagget <code>operator=Norwich City Council</code> markeres med en farvet firkant svarende til <code>colour</code>-tagget.</p>\n"},elevationprofiles:{title:"Højdeprofiler",general:'<p>Højdeprofilerne laves ved hjælp af af højdedata fra <a href="http://asterweb.jpl.nasa.gov/gdem.asp">ASTER global digital højdemodel (GDEM) version 2</a>, og hverken &quot;ele&quot;-tagget i OpenStreetMap eller tunneller og broer medregnes.</p>\n<p>Hvis ruten har flere end to endepunkter eller består af mere end et segment, vil der ikke blive vist nogen højdeprofil. Retningen på profilen følger ruten fra vest mod øst eller fra nord mod syd. Hvis ruterne havde elementer med roller som &quot;start&quot; og &quot;mål&quot; og/eller var listet op kontinuert fra start til slut, ville vi måske være istand til at bestemme retningen på ruten ud fra selve relationen. Du kan eventuelt holde dette i tankerne, hvis du kortlægger ruter på OpenStreetMap.</p>\n<p>Der er huller, såkaldte &quot;tomrum&quot;, hvor vi ikke har nogen højdedata. Disse vises med huller i højdeprofillinjen.</p>\n<p>Bemærk, at selvom ASTER version 2 nok er den bedste, frie, globale DEM, har den sine begrænsninger med hensyn til nøjagtighed og dækning, se deres <a href="http://www.jspacesystems.or.jp/ersdac/GDEM/ver2Validation/Summary_GDEM2_validation_report_final.pdf">konklusionsrapport angående valideringen</a> for flere oplysninger. Unøjagtighederne forværres yderligere af unøjagtigheden af dataene i OSM, <a href="https://github.com/waymarkedtrails/waymarked-trails-site/commit/602e12f38bfdc50c7e07bd3f44e080d72bcbb2a2">en udglatningsteknik</a>, vi anvender, og opløsningen af profilen, som bliver lavere, jo længere ruten bliver.</p>\n'},technical:{title:"Tekniske detaljer",general:'<p>Rutekortlaget opdateres hvert minut og er normalt 2-5 minutter efter OSM-serveren. Datoen i det øverste venstre hjørne angiver den seneste opdatering. Opdateringer af det underliggende Mapnik-kort bliver ikke styret af denne hjemmeside. Afhængigt af belastningen på OSM-serveren vil de tage mellem et minut og nogle få timer.</p>\n<p>Kildekoden til denne hjemmeside er tilgængelig under en GPL-licens og fordelt over flere arkiver:</p>\n<ul>\n<li><a href="https://github.com/waymarkedtrails/waymarkedtrails-backend/">backend-kode og kortgenerering</a></li>\n<li><a href="https://github.com/waymarkedtrails/waymarkedtrails-api/">API-tjeneste</a></li>\n<li><a href="https://github.com/waymarkedtrails/waymarkedtrails-website/">hjemmeside-frontend</a></li>\n</ul>\n<p>Hvis du blot vil rapportere en fejl eller diskutere funktioner på hjemmesiden, kan du bruge <a href="https://github.com/waymarkedtrails/waymarked-trails-site/issues">issue tracker</a>\neller <a href="https://github.com/waymarkedtrails/waymarked-trails-site/discussions">diskussionsfunktionen</a> i projektarkivet på Github.</p>\n',translation:'<h2>Oversættelser</h2>\n<p>Oversættelser håndteres af de evigt hjælpsomme folk på <a href="https://translatewiki.net">translatewiki.net</a>. Hvis du har lyst til at bidrage med en oversættelse til dit eget sprog eller give kommentarer til de eksisterende oversættelser, kan du besøge <a href="https://translatewiki.net/wiki/Translating:Waymarked_Trails">projektsiden på translatewiki.net</a>.</p>\n'},legal:{title:"Juridiske betingelser og betingelser for brug",copyright:'<p>Rutekortlaget er tilgængelig under <a href="https://creativecommons.org/licenses/by-sa/3.0/de/deed.en">Creative Commons Navngivelse-DelPåSammeVilkår 3.0 Tyskland-licensen</a> og GPX-sporene er under <a href="https://opendatacommons.org/licenses/odbl/">ODbL</a>. De kan genbruges og ændres, så længe det resulterende værk bruger en kompatibel licens, og OpenStreetMap-projektet og denne hjemmeside nævnes.</p>\n',usage:"<h2>Betingelser for brug</h2>\n<p>Du må godt bruge kortlaget på andre hjemmesider, så længe trafikmængden er moderat. Vær så venlig at mellemlagre kortbillederne så meget som muligt og angive en korrekt HTTP-&quot;referrer&quot;. Massedownload af kortbilleder frarådes på det stærkeste.</p>\n<p>GPX-spor er gjort tilgængelig som et hjælpemiddel for brugere af denne side. Massedownload er ikke tilladt.</p>\n",disclaimer:"<h2>Ansvarsfraskrivelse</h2>\n<p>Hverken kortets korrekthed eller fuldstændighed kan garanteres. Hvis du tager ud på en vandretur, så medbring et godt papirkort, det passende udstyr og din almindelige, sunde fornuft. Naturen kan være så hensynsløs, som den er smuk.</p>\n<p>Denne hjemmeside indeholder henvisninger til eksterne hjemmesider. Forfatteren af denne hjemmeside har ingen indflydelse på indholdet af disse hjemmesider og tager intet ansvar for det.</p>\n"},acknowledgements:{title:"Tak til",text:'<p>Alle kortdata stammer fra <a href="https://www.openstreetmap.org">OpenStreetMap og dets bidragydere</a> og er gjort tilgængelig under ODbl-licensen. Grundkortet stammer også fra OSM. Der er flere oplysninger på <a href="https://www.openstreetmap.org/copyright">OSMs side om ophavsret</a>.</p>\n<p>Højdeprofillaget og højdekurverne kommer fra en sammenblanding af SRTM- og ASTER GDEM-data. ASTER GDEM er lavet af METI og NASA. Efterbehandlingen blev venligst stillet til råde af Yves Cainaud fra <a href="https://opensnowmap.org">opensnowmap.org</a>.</p>\n<p>Højdeprofilkoden er udviklet af Espen Oldeman Lund i samarbejde med <a href="https://www.kresendo.no">Kresendo</a> og TG4NP-projektet på <a href="https://www.vestforsk.no">Western Norway Research Institute</a>.</p>\n<p>Vintersportspisteudgaven er udviklet af Michael Spreng. Ridningssymbolet er\nudarbejdet af Robert Whittaker.</p>\n<p>Oversættelser af denne hjemmeside kommer fra <a href="https://translatewiki.net/wiki/Category:Waymarked_Trails_translators">translatewiki.net og dens bidragydere</a>. En særskilt tak går til de pionæroversættere, der bidrog med oversættelser før translatewiki.net: Yves Cainaud (fransk),\nOscar Formaggi (italiensk),\nGustavo <a href="http://www.blogger.com/profile/12473561703699888751">Tuentibiker</a> Ramis (spansk),\n<a href="https://guttormflatabo.com">Guttorm Flatabø</a>/TG4NP (norsk bokmål og nynorsk),\nMads Lumholt/TG4NP (dansk), Magnús Smári Snorrason/TG4NP (islandsk),\nLars Mikaelsson/TG4NP (svensk) og Elina Pesonen (finsk).</p>\n'},contact:{title:"Kontakt",text:'<p>Spørgsmål og kommentarer til denne hjemmeside kan sendes til: <a href="mailto:lonvia@denofr.de">lonvia@denofr.de</a>.</p>\n<p>Tekniske fejl kan også rapporteres på [projektets fejlhåndtering på <a href="https://github.com/waymarkedtrails/waymarked-trails-site/issues">github</a>. Før du indrapporterer en fejl, bedes du kontrollere at problemet ikke skyldes dataene i OSM.</p>\n'}},r=e.about,t=e.rendering,n=e.route_order,i=e.hierarchies,a=e.osmc,s=e.hikinglocal,o=e.elevationprofiles,l=e.technical,d=e.legal,g=e.acknowledgements,k=e.contact;export{r as about,g as acknowledgements,k as contact,e as default,o as elevationprofiles,i as hierarchies,s as hikinglocal,d as legal,a as osmc,t as rendering,n as route_order,l as technical};
